SELECT COUNT(*) FROM users as u, comments as c, posts as p, postLinks as pl WHERE pl.RelatedPostId = p.Id AND c.PostId = p.Id AND u.Id= c.UserId AND u.Reputation>=1 AND u.Reputation<=491 AND u.DownVotes>=0 AND u.DownVotes<=0 AND c.CreationDate>='2010-07-11 12:25:05'::timestamp AND c.CreationDate<='2014-09-11 13:43:09'::timestamp AND p.CommentCount>=0 AND p.CommentCount<=14 AND pl.LinkTypeId=1;